<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\Event;

use Override;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\UserPersonalApiKey;

class UserPersonalApiKeyRevokeEvent extends UserPersonalApiKeyUpdateEvent
{
    public function __construct(
        UserPersonalApiKey $payload,
        UserPersonalApiKey $original
    ) {
        parent::__construct($payload, $original);
    }
    #[Override]
    public function eventType(): string
    {
        return 'user-personal-api-key.revoke';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return $this->original->asPublicJson();
    }
}
